int main(void)
{
    int n, m, i;
    int alive[205];
    int pos = -1;                    /* 上一轮出圈者的位置，从 -1 起便于统一前进 */

    if (scanf("%d %d", &n, &m) != 2)
        return 0;
    for (i = 0; i < n; i++)
        alive[i] = 1;                /* 1 表示还在圈内 */

    for (i = 0; i < n; i++) {
        int cnt = 0;

        while (cnt < m) {
            pos = (pos + 1) % n;     /* 下标在圈内循环前进 */
            if (alive[pos])
                cnt++;               /* 已出圈的人不再报数 */
        }
        alive[pos] = 0;
        if (i > 0)
            printf(" ");
        printf("%d", pos + 1);
    }
    printf("\n");
    return 0;
}

