                break;
            }
            t /= 10;                 /* 去掉末位 */
        }
        if (has && x % 3 == 0) {
            cnt++;
            if (first < 0)
                first = x;
        }
    }

    printf("%d\n", cnt);
    printf("%d\n", first);
    return 0;
}

