        total += used[i];
    }

    printf("%d\n", total);
    if (total == 0) {
        printf("none\n");
        return 0;
    }
    {
        int first = 1;

        for (i = 0; i < 7; i++) {
            if (used[i] > 0) {
                if (!first)
                    printf(" ");
                printf("%d:%d", coin[i], used[i]);
                first = 0;
            }
        }
        printf("\n");
    }
    return 0;
}

