{
    int n, i, j;
    int a[1005];
    long long swaps = 0;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    for (i = 0; i < n - 1; i++) {
        int swapped = 0;

        for (j = 0; j < n - 1 - i; j++) {      /* 末尾 i+1 个已经就位 */
            if (a[j] > a[j + 1]) {
                int t = a[j];

                a[j] = a[j + 1];
                a[j + 1] = t;
                swaps++;                       /* 每交换一次计一次 */
                swapped = 1;
            }
        }
        if (!swapped)
            break;                             /* 本轮无交换说明已经有序 */
    }

    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", a[i]);
    }
    printf("\nswaps: %lld\n", swaps);
    return 0;
}

