def lower_bound(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])
    a = [int(v) for v in data[2:2 + n]]
    queries = data[2 + n:2 + n + q]

    out = []
    for token in queries:
        x = int(token)
        pos = lower_bound(a, x)
        if pos < n and a[pos] == x:
            out.append(str(pos + 1))
        else:
            out.append("-1")

    sys.stdout.write("\n".join(out) + "\n")

