#include <stdio.h>
#include <stdlib.h>

static int cmp_int(const void *p, const void *q)
{
    int x = *(const int *)p;
    int y = *(const int *)q;

    return (x > y) - (x < y);
}

int main(void)
{
    static int a[100005];
    int n, i, k = 0;
    int best = 0, bestCnt = 0;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    qsort(a, (size_t)n, sizeof(int), cmp_int);

    i = 0;
    while (i < n) {
        int j = i;
        int v = a[i];

        while (j < n && a[j] == v)
            j++;
        a[k++] = v;                 /* 去重结果就地写回数组前部 */
        if (j - i > bestCnt) {      /* 严格大于，并列时保留较小的 v */
            bestCnt = j - i;
            best = v;
        }
        i = j;
    }

    printf("distinct: %d\n", k);
    for (i = 0; i < k; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", a[i]);
    }
    printf("\nmode: %d cnt: %d\n", best, bestCnt);
    return 0;
}

