    char w[505];
    char best[505];
    int words = 0, bestLen = 0, letters = 0;

    best[0] = '\0';
    while (scanf("%504s", w) == 1) {
        size_t len = strlen(w);

        while (len > 0 && (w[len - 1] == ',' || w[len - 1] == '.' ||
                           w[len - 1] == '!' || w[len - 1] == '?')) {
            w[--len] = '\0';
        }
        if (len == 0)
            continue;

        words++;
        letters += (int)len;
        if ((int)len > bestLen) {     /* 严格大于，并列时保留先出现的 */
            bestLen = (int)len;
            strcpy(best, w);
        }
    }

    printf("words: %d\n", words);
    printf("longest: %s len: %d\n", best, bestLen);
    printf("letters: %d\n", letters);
    return 0;
}

