int main(void)
{
    static int a[100005];
    int n, i;
    long long cur, best;
    int curStart = 1, bestL = 1, bestR = 1;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    cur = a[0];
    best = a[0];

    for (i = 1; i < n; i++) {
        if (cur < 0) {          /* 前面的部分和为负，丢掉它从 a[i] 重新开始 */
            cur = a[i];
            curStart = i + 1;
        } else {
            cur += a[i];
        }
        if (cur > best) {       /* 严格大于：并列时保留起点更小的旧答案 */
            best = cur;
            bestL = curStart;
            bestR = i + 1;
        }
    }

    printf("sum: %lld\n", best);
    printf("range: %d %d\n", bestL, bestR);
    return 0;
}

